/* Sound: wrappers of the bank 7 routines (SoundInit $CEDD, SoundUpdate $CEE5, SoundPlay $CF0D) around the driver of the
 * bank 0 (sound_engine.c: $901E init, $864C update, $905F command).
 *
 * Built with --snddiff (python build.py --snddiff) and SNDDIFF=1 at run time: each call is redone on a copy
 * with the driver mechanically translated from the ROM (tools/sound_oracle.c, generated by tools/asm2c.py) and the results (sound RAM,
 * APU writes) are compared; the differences are written to the log ("SNDDIFF ..."). SNDALL=1 also plays every sound $00-$FF. */
#include <stdlib.h>
#include <string.h>
#include "game.h"
#include "sound.h"

void sound_engine_init(Game *g);
void sound_engine_play(Game *g, uint8_t id);
void sound_engine_update(Game *g);

#ifdef SNDDIFF
void sound_driver_call(Game *g, uint16_t entry, uint8_t a, uint8_t x, uint8_t y);
extern Game *apu_dbg_g[2];
extern int apu_dbg_n[2];
extern uint16_t apu_dbg_log[2][4096];

static void compare_with_model(Game *g, Game *sh, int what, uint8_t id) {
    static const uint16_t entry[3] = {0x901E, 0x905F, 0x864C};
    sound_driver_call(sh, entry[what], id, 0, 0);
    int bad = 0;
    for (int i = 0; i < 0x1A7 && bad < 6; i++) {
        if (i >= 0xE0 && i < 0xEC) {
            continue; /* temporaries of the model */
        }
        if (i >= 0xEE && i < 0x100) {
            continue;
        }
        if (g->ram[i] != sh->ram[i]) {
            TRACE("f=%u SNDDIFF ram $%04X port=%02X model=%02X (call %d id %02X)\n", g->frame, i, g->ram[i], sh->ram[i], what, id);
            bad++;
        }
    }
    if (apu_dbg_n[0] != apu_dbg_n[1] || memcmp(apu_dbg_log[0], apu_dbg_log[1], (size_t)apu_dbg_n[0] * 2)) {
        TRACE("f=%u SNDDIFF apu : %d writes, %d in model (call %d id %02X)\n", g->frame, apu_dbg_n[0], apu_dbg_n[1], what, id);
        for (int i = 0; i < apu_dbg_n[0] && i < apu_dbg_n[1]; i++) {
            if (apu_dbg_log[0][i] != apu_dbg_log[1][i]) {
                TRACE("   #%d port=%04X model=%04X\n", i, apu_dbg_log[0][i], apu_dbg_log[1][i]);
                break;
            }
        }
    }
}
#endif

/* what: 0 init, 1 command, 2 update */
static void engine(Game *g, int what, uint8_t id) {
#ifdef SNDDIFF
    static int diff = -1;
    if (diff < 0) {
        diff = getenv("SNDDIFF") != NULL;
    }
    Game *sh = NULL;
    if (diff) {
        sh = malloc(sizeof *sh);
        *sh = *g;
        sh->trace = NULL;
        apu_dbg_g[0] = g;
        apu_dbg_g[1] = sh;
        apu_dbg_n[0] = apu_dbg_n[1] = 0;
    }
#endif
    if (what == 0) {
        sound_engine_init(g);
    } else if (what == 1) {
        sound_engine_play(g, id);
    } else {
        sound_engine_update(g);
    }
#ifdef SNDDIFF
    if (diff) {
        compare_with_model(g, sh, what, id);
        apu_dbg_g[0] = apu_dbg_g[1] = NULL;
        free(sh);
    }
#endif
}

void sound_init(Game *g) {
    TRACE("f=%u SoundInit\n", g->frame);
    engine(g, 0, 0);
}

void sound_play(Game *g, uint8_t id) {
    TRACE("frame=%u SoundPlay(%02X)\n", g->frame, id);
    M(SoundTemp) = id;
    if (M(SoundBusy) & 0x80) {
        return;
    }
    M(SoundBusy) = 0x80;
    engine(g, 1, id);
    M(SoundBusy) <<= 1;
}

void sound_update(Game *g) /* called once per frame, in the NMI */
{
    if (M(MapperBusy) & 0x80) {
        return;
    }
    if (M(SoundBusy) & 0x80) {
        return;
    }
    M(SoundBusy) = 0x80;
    engine(g, 2, 0);
    M(SoundBusy) = 0;
}
